CREATE TABLE ip_t(id int);
CREATE TABLE ip_e(id int);
CREATE TABLE ip_z(x int);
INSERT INTO ip_t VALUES (1),(2),(3);
INSERT INTO ip_z VALUES (0);
SELECT (SELECT 1/x FROM ip_z) FROM ip_e;
SELECT (SELECT 1/x FROM ip_z) FROM ip_t;
SELECT CASE WHEN id > 100 THEN (SELECT 1/x FROM ip_z) END FROM ip_t;
SELECT * FROM ip_e WHERE (SELECT 1/x FROM ip_z) > 0;
SELECT * FROM ip_t WHERE id > 5 AND (SELECT 1/x FROM ip_z) > 0;
SELECT * FROM ip_t WHERE (SELECT x FROM ip_z) > 0 AND 1/(id - 1) > 0;
SELECT 1/(id-1) FROM ip_t WHERE (SELECT x FROM ip_z) > 0;
SELECT count(*) FROM ip_e HAVING (SELECT 1/x FROM ip_z) > 0;
SELECT count(*) FROM ip_t HAVING (SELECT x FROM ip_z) > 0;
SELECT id FROM ip_t WHERE EXISTS (SELECT 1 FROM ip_z WHERE x > 0) AND 1/(id-1) > 0;
SELECT id, (SELECT max(x) FROM ip_z) FROM ip_t ORDER BY id LIMIT 1;
SELECT ARRAY(SELECT 1/x FROM ip_z) FROM ip_e;
SELECT EXISTS (SELECT 1/x FROM ip_z) FROM ip_e;
SELECT (SELECT 1/x FROM ip_z), count(*) FROM ip_e;
SELECT CASE WHEN id > 100 THEN (SELECT 1/x FROM ip_z) END FROM ip_t ORDER BY id;
SELECT id, CASE WHEN id > 100 THEN (SELECT 1/x FROM ip_z) END FROM ip_t, ip_e;
SELECT count(*) FROM ip_t WHERE (SELECT x FROM ip_z) > 0 GROUP BY id;
SELECT id FROM ip_t WHERE (SELECT x FROM ip_z) = 0 ORDER BY id DESC;
BEGIN;
DECLARE ip_c CURSOR FOR SELECT (SELECT 1/x FROM ip_z) FROM ip_e;
FETCH ALL FROM ip_c;
COMMIT;
